cat > probe_shutdown_test.go <<'EOF'
package main

import (
	"net"
	"net/http"
	"sync/atomic"
	"testing"
	"time"
)

func TestProbeShutdown(t *testing.T) {
	var inflight atomic.Int32
	inflight.Store(1)
	mux := http.NewServeMux()
	mux.HandleFunc("/slow", func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(800 * time.Millisecond)
		inflight.Store(0)
		w.WriteHeader(http.StatusOK)
	})
	server := &http.Server{Handler: mux}
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	go server.Serve(ln)
	time.Sleep(100 * time.Millisecond)

	// Fire the slow request, then shut down WHILE it is in flight.
	done := make(chan error, 1)
	go func() {
		resp, err := http.Get("http://" + ln.Addr().String() + "/slow")
		if err == nil {
			resp.Body.Close()
		}
		done <- err
	}()
	time.Sleep(200 * time.Millisecond) // request is now in flight
	if err := shutdown(server); err != nil {
		t.Fatalf("shutdown error: %v", err)
	}
	// Graceful: the in-flight request completes successfully.
	if err := <-done; err != nil {
		t.Fatalf("in-flight request did not complete gracefully: %v", err)
	}
	if inflight.Load() != 0 {
		t.Fatal("handler did not run to completion")
	}

	// The listener must actually be closed: new connections fail.
	conn, err := net.DialTimeout("tcp", ln.Addr().String(), 500*time.Millisecond)
	if err == nil {
		conn.Close()
		t.Fatal("server still accepting connections after shutdown")
	}

	// Second shutdown on the stopped server: no error.
	if err := shutdown(server); err != nil {
		t.Fatalf("second shutdown error: %v", err)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_shutdown_test.go ; exit $rc

